-- What else may have changed when objects of a type did: the objects that read them through a relation (a
-- dot, inheritance, a group's members, a group inside a group), then those that read those, until nothing
-- is new. Past 1000 objects of a type: all of them ({*}), and all of what reads them. Each is
-- announced with the cause 'dependent'.
CREATE OR REPLACE FUNCTION authz_int.dependents(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE
  v_all boolean := '*' = ANY (p_ids);
  v_rows bigint; v_most int;
  -- for each type: the ids known (s), new in the last round (n), found in this one (x), how many were found (c),
  -- and whether it is all of them (a)
  s1 integer[] := '{}'; n1 integer[] := '{}'; x1 integer[]; c1 int := 0; a1 boolean := false;  -- folder
  s2 integer[] := '{}'; n2 integer[] := '{}'; x2 integer[]; c2 int := 0; a2 boolean := false;  -- note
  s3 integer[] := '{}'; n3 integer[] := '{}'; x3 integer[]; c3 int := 0; a3 boolean := false;  -- project
BEGIN
  CASE p_type
    WHEN 'folder' THEN
      IF v_all THEN a1 := true;
      ELSE n1 := ARRAY(SELECT DISTINCT x::integer FROM unnest(p_ids) x WHERE pg_input_is_valid(x, 'integer')); s1 := n1;
      END IF;
    WHEN 'project' THEN
      IF v_all THEN a3 := true;
      ELSE n3 := ARRAY(SELECT DISTINCT x::integer FROM unnest(p_ids) x WHERE pg_input_is_valid(x, 'integer')); s3 := n3;
      END IF;
    ELSE RETURN;  -- nothing reads its objects
  END CASE;
  LOOP
    -- all of a type: all of what reads it too
    IF a3 THEN a2 := true; END IF;
    EXIT WHEN (a1 OR cardinality(n1) = 0) AND (a2 OR cardinality(n2) = 0) AND (a3 OR cardinality(n3) = 0);
    IF NOT a1 AND (cardinality(n1) > 0) THEN
      v_most := cardinality(s1) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (authz__.s1)), '{}')
        INTO v_rows, x1
        FROM (SELECT x."id" FROM "app"."folders" x WHERE x."parent_id" = ANY (authz__.n1) AND cardinality(authz__.n1) > 0
          LIMIT authz__.v_most) d(v);
      a1 := v_rows >= v_most;
    ELSE
      x1 := '{}';
    END IF;
    IF NOT a2 AND (cardinality(n3) > 0) THEN
      v_most := cardinality(s2) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (authz__.s2)), '{}')
        INTO v_rows, x2
        FROM (SELECT x."id" FROM "app"."notes" x WHERE x."project_id" = ANY (authz__.n3) AND cardinality(authz__.n3) > 0
          LIMIT authz__.v_most) d(v);
      a2 := v_rows >= v_most;
    ELSE
      x2 := '{}';
    END IF;
    n1 := x1; s1 := s1 || x1; c1 := c1 + cardinality(x1); a1 := a1 OR c1 > 1000;
    n2 := x2; s2 := s2 || x2; c2 := c2 + cardinality(x2); a2 := a2 OR c2 > 1000;
    n3 := '{}';
  END LOOP;
  IF a1 AND NOT (v_all AND p_type = 'folder') THEN
    PERFORM authz_int.announce('folder', '{*}', 'dependent', false);
  ELSIF NOT a1 AND c1 > 0 THEN
    PERFORM authz_int.announce('folder', ARRAY(SELECT v::text FROM unnest(s1[cardinality(s1) - c1 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
  IF a2 AND NOT (v_all AND p_type = 'note') THEN
    PERFORM authz_int.announce('note', '{*}', 'dependent', false);
  ELSIF NOT a2 AND c2 > 0 THEN
    PERFORM authz_int.announce('note', ARRAY(SELECT v::text FROM unnest(s2[cardinality(s2) - c2 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
END $f$;
--> statement-breakpoint
-- a role that gives more or less: the objects it is given on (its assignments are shares, 'role:<id>'; a change:
-- the roles it was in and is in)
CREATE OR REPLACE FUNCTION authz_int.on_role_permissions() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
BEGIN
  IF TG_OP = 'UPDATE' THEN
    PERFORM authz_int.changed(g.object_type, array_agg(DISTINCT g.object_id), 'role')
    FROM authz.shares g WHERE g.relation IN (SELECT 'role:' || r.role_id FROM role_rows r
                                             UNION SELECT 'role:' || n.role_id FROM new_role_rows n) GROUP BY g.object_type;
  ELSE
    PERFORM authz_int.changed(g.object_type, array_agg(DISTINCT g.object_id), 'role')
    FROM authz.shares g WHERE g.relation IN (SELECT 'role:' || r.role_id FROM role_rows r) GROUP BY g.object_type;
  END IF;
  RETURN NULL;
END $f$;
