        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."projects" o WHERE o."id" = authz__.v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."project__member" v WHERE v.id = o."id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."projects" o WHERE o."id" = authz__.v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce((public), false)
    OR EXISTS (SELECT 1 FROM authz_int."project__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."project__service" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."project__viewer" v WHERE v.id = o."id"))));
        WHEN 'share' THEN RETURN EXISTS (SELECT 1 FROM "app"."projects" o WHERE o."id" = authz__.v_integer AND (coalesce(o."owner_id" = (SELECT authz.uid()), false))
    AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR coalesce((public), false)
    OR EXISTS (SELECT 1 FROM authz_int."project__member" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."project__service" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."project__viewer" v WHERE v.id = o."id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'note' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."notes" o WHERE o."id" = authz__.v_integer AND ((coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."project__owner" v WHERE v.id = o."project_id")))
    AND (EXISTS (SELECT 1 FROM authz_int."project__view" v WHERE v.id = o."project_id")));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."notes" o WHERE o."id" = authz__.v_integer AND (EXISTS (SELECT 1 FROM authz_int."project__view" v WHERE v.id = o."project_id")));
