CREATE OR REPLACE FUNCTION authz_int."project__view__why"(p_id integer, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."project__view");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'project.view = edit or service or viewer or {public}';
  BEGIN
    v_ok := ($1) IN (SELECT id FROM authz_int."project__edit");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'edit';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."project__edit__why"($1, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := ($1) IN (SELECT id FROM authz_int."project__service");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'service';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."project__service__why"($1, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := ($1) IN (SELECT id FROM authz_int."project__viewer");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'viewer';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."project__viewer__why"($1, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := ($1) IN (SELECT r."id" AS id FROM "app"."projects" r WHERE coalesce((public), false));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{public}';
  END;
END $f$;
