-- May the signed-in user see this object (select it)? A hidden object reads as a missing one
CREATE OR REPLACE FUNCTION authz_int.visible(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  IF NOT coalesce(pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)), false) THEN
    RETURN false;
  END IF;
  CASE p_type
    WHEN 'user' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."users" "users" WHERE "users"."id" = $2::integer
        AND true);
    WHEN 'service' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."services" "services" WHERE "services"."id" = $2::integer
        AND true);
    WHEN 'project' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."projects" "projects" WHERE "projects"."id" = $2::integer
        AND (SELECT authz_int.scope_cmd('app.projects', 'select')) AND (coalesce("projects"."owner_id" = (SELECT authz.uid()), false)
    OR coalesce((public), false)
    OR EXISTS (SELECT 1 FROM authz_int."project__member" v WHERE v.id = "projects"."id")
    OR EXISTS (SELECT 1 FROM authz_int."project__service" v WHERE v.id = "projects"."id")
    OR EXISTS (SELECT 1 FROM authz_int."project__viewer" v WHERE v.id = "projects"."id")));
    WHEN 'note' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."notes" "notes" WHERE "notes"."id" = $2::integer
        AND (SELECT authz_int.scope_cmd('app.notes', 'select')) AND EXISTS (SELECT 1 FROM authz_int."project__view" v WHERE v.id = "notes"."project_id"));
    WHEN 'message' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."inbox" "inbox" WHERE "inbox"."id" = $2::integer
        AND (SELECT authz_int.scope_cmd('app.inbox', 'select')) AND coalesce("inbox"."recipient_id" = (SELECT authz.uid()), false));
    WHEN 'folder' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."folders" "folders" WHERE "folders"."id" = $2::integer
        AND (SELECT authz_int.scope_cmd('app.folders', 'select')) AND (coalesce("folders"."owner_id" = (SELECT authz.uid()), false)
    OR authz_int."folder__edit__has"("folders"."parent_id")));
    ELSE RETURN false;
  END CASE;
END $f$;
