-- Everyone who holds a permission on an object: SELECT * FROM authz.who('folder', 3, 'view')
-- Candidates come from the data (a superset); each is checked as that user (the permission itself, authz_int.can).
CREATE OR REPLACE FUNCTION authz.who(p_type text, p_id text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_c text;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_integer integer;
BEGIN
  IF NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm) THEN
    RAISE EXCEPTION 'you cannot see who has access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- (the caller's settings are put back below; an error needs nothing put back: Postgres undoes these settings with
  -- the transaction, or the savepoint the error is caught at, as for explain, check_invariants and the logins)
  PERFORM set_config('authz.scopes', '', true);   -- each candidate is checked with full rights
  PERFORM set_config('authz.principal_type', '', true);   -- candidates are users
  <<asking>> BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'service' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'project' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."project__edit__who"(authz__.v_integer) c(id) WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."project__view__who"(authz__.v_integer) c(id) WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'share' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."project__share__who"(authz__.v_integer) c(id) WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'note' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."note__edit__who"(authz__.v_integer) c(id) WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."note__view__who"(authz__.v_integer) c(id) WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'read' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."message__read__who"(authz__.v_integer) c(id) WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN EXIT asking; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."folder__edit__who"(authz__.v_integer) c(id) WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;
